member.example:
Creating a derived ERP structure for processing through code.

            	public SomeTransaction() :
            		base()
            	{
            		TxType = "SomeTransaction";
            		_Fields.AddRange(new string[]
            				 {
            				"Field1",
            				"Field2",
            				"Field3",
            				"Field4",
            				"Field5",
            				"Field6",
            				"Field7"
            				});
            		}

Example of adding new field.

            SomeTransAction.Initialize();
            SomeTransAction.Field1 = "Test1";
            SomeTransAction.Field2 = "Test2";
            SomeTransAction.AddField("NewField");
            SomeTransAction.SetField("NewField", "Test3");

            //Output Fields node.
            <Fields>
            	<Field name="Field1" value="Test1" />
            	<Field name="Field2" value="Test2" />
            	<Field name="NewField" value="Test3" />
            </Fields>

Example of preparing transaction for send.

            	//_Transactions part of BaseWorkflow.
            	Custom.ERPI.SomeTransaction _SomeTransAction = new SomeTransaction();
            	_Transactions.Add(_SomeTransAction);
            	_SomeTransAction.Initialize();
            	_SomeTransAction.Field1 = "Test1";
            	_SomeTransAction.Field2 = "Test2";
            	_Transactions.Send("True");

Use of AddToBoundary

            //Transactions part of BaseWorkflow.
            Custom.ERPI.SomeTransaction ERPTransaction = new SomeTransaction();
            Transactions.Add(ERPTransaction);
            ERPTransaction.Initialize();
            ERPTransaction.Field1 = "Test1";
            ERPTransaction.Field2 = "Test2";
            ERPTransaction.AddToBoundary();
            ERPTransaction.Field1 = "Test3";
            ERPTransaction.Field2 = "Test4";
            Transactions.Send("True");


            		//Transaction child nodes.
               <Transaction Boundary="1" erp="PeopleSoft">
              <Tx Sequence="1" name="SomeTransaction" Boundary="1">
            <Fields>
            	<Field name="Field1" value="Test1" />
            	<Field name="Field2" value="Test2" />
            </Fields>
              </Tx>
              <Tx Sequence="2" name="SomeTransaction" Boundary="1">
            <Fields>
            	<Field name="Field1" value="Test3" />
            	<Field name="Field2" value="Test4" />
            </Fields>
              </Tx>
            </Transaction>

Use of AddToBoundaryWithData

            //Transactions part of BaseWorkflow.
            Custom.ERPI.SomeTransaction ERPTransaction = new SomeTransaction();
            Transactions.Add(ERPTransaction);
            ERPTransaction.Initialize();
            ERPTransaction.Field1 = "Test1";
            ERPTransaction.Field2 = "Test2";
            ERPTransaction.AddToBoundaryWithData();
            ERPTransaction.Field2 = "Test4";
            Transactions.Send("True");


            		//Transaction child nodes.
               <Transaction Boundary="1" erp="PeopleSoft">
              <Tx Sequence="1" name="SomeTransaction" Boundary="1">
            <Fields>
            	<Field name="Field1" value="Test1" />
            	<Field name="Field2" value="Test2" />
            </Fields>
              </Tx>
              <Tx Sequence="2" name="SomeTransaction" Boundary="1">
            <Fields>
            	<Field name="Field1" value="Test1" />
            	<Field name="Field2" value="Test4" />
            </Fields>
              </Tx>
            </Transaction>
